/* ---- Sidebar & Auxiliary Bar Card Appearance ---- */

/**
 * The auxiliary bar and panel use a card-like appearance with margins and border-radius
 * applied directly on the .part element. The grid allocates full space; CSS margin shrinks
 * the part within its split-view-view wrapper. Layout dimensions are reduced in code
 * (AgenticAuxiliaryBarPart) to keep internal layout correct.
 *
 * No z-index or stacking-context changes - sashes render naturally on top.
 *
 * Margin values (must match the constants in the Part classes):
 *   Sidebar:       no card (flush, spans full height)
 *   Auxiliary bar:  top=16, bottom=18, right=16
 *   Panel:          bottom=18, left=16, right=16
 */

.agent-sessions-workbench .part.sidebar {
	background: var(--vscode-sideBar-background);
	border-right: 1px solid var(--vscode-sideBar-border, transparent);
}

.agent-sessions-workbench .part.auxiliarybar {
	margin: 16px 16px 18px 0;
	background: var(--part-background);
	border: 1px solid var(--part-border-color, transparent);
	border-radius: 8px;
}

.agent-sessions-workbench .part.panel {
	margin: 0 16px 18px 16px;
	background: var(--part-background);
	border: 1px solid var(--part-border-color, transparent);
	border-radius: 8px;
}

/* Grid background matches the chat bar / sidebar background */
.agent-sessions-workbench > .monaco-grid-view {
	background-color: var(--vscode-sideBar-background);
}

/* ---- Chat Layout ---- */

/* Remove max-width from the session container so the scrollbar extends full width */
.agent-sessions-workbench .interactive-session {
	max-width: none;
}

/* Constrain content items to the same max-width, centered */
.agent-sessions-workbench .interactive-session .interactive-item-container {
  max-width: 950px;
  margin: 0 auto;
  padding-left: 16px;
  padding-right: 16px;
  box-sizing: border-box;
}

/* Target specific container elements for chat session header injection */
.agent-sessions-workbench .chat-header-container {
  max-width: 950px;
  margin: 0 auto;
  padding-left: 16px;
  padding-right: 16px;
  box-sizing: border-box;
}

.agent-sessions-workbench .chat-header-container .chat-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  background-color: var(--vscode-sideBar-background);
  border-bottom: 1px solid var(--vscode-sideBar-border, transparent);
}

.agent-sessions-workbench .chat-header-container .chat-header .chat-title {
  font-size: 16px;
  font-weight: bold;
}

.agent-sessions-workbench .chat-header-container .chat-header .chat-actions {
  display: flex;
  gap: 8px;
}

.agent-sessions-workbench .chat-header-container .chat-header .chat-actions button {
  padding: 4px 8px;
  border: 1px solid var(--vscode-sideBar-border, transparent);
  border-radius: 4px;
  background-color: transparent;
  cursor: pointer;
}

.agent-sessions-workbench .chat-header-container .chat-header .chat-actions button:hover {
  background-color: var(--vscode-sideBar-hoverBackground);
}

.agent-sessions-workbench .interactive-session > .chat-suggest-next-widget {
  max-width: 950px;
  margin: 0 auto;
  padding-left: 16px;
  padding-right: 16px;
  box-sizing: border-box;
}
